export async function listTools() {
  return [
    {
      name: 'calculate',
      description: 'Perform a basic arithmetic operation on two numbers.',
      inputSchema: {
        type: 'object',
        properties: {
          a: { type: 'number' },
          b: { type: 'number' },
          operation: { type: 'string', enum: ['add', 'subtract', 'multiply', 'divide'] }
        },
        required: ['a', 'b', 'operation'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args) {
  if (name !== 'calculate') {
    throw new Error(`Unknown tool: ${name}`);
  }

  const argsObj = args == null ? {} : args;
  const allowedKeys = new Set(['a', 'b', 'operation']);
  const argKeys = Object.keys(argsObj);
  const extraKeys = argKeys.filter(k => !allowedKeys.has(k));
  if (extraKeys.length > 0) {
    throw new Error(`Unexpected argument(s): ${extraKeys.join(', ')}`);
  }

  const { a, b, operation } = argsObj;

  if (typeof a !== 'number' || typeof b !== 'number' || Number.isNaN(a) || Number.isNaN(b)) {
    throw new Error('Invalid arguments: a and b must be numbers');
  }
  if (!['add', 'subtract', 'multiply', 'divide'].includes(operation)) {
    throw new Error(`Unsupported operation: ${operation}`);
  }

  let result;
  switch (operation) {
    case 'add':
      result = a + b;
      break;
    case 'subtract':
      result = a - b;
      break;
    case 'multiply':
      result = a * b;
      break;
    case 'divide':
      if (b === 0) {
        throw new Error('Division by zero');
      }
      result = a / b;
      break;
    default:
      throw new Error(`Unsupported operation: ${operation}`);
  }

  return { content: [{ type: 'text', text: String(result) }] };
}
